//! Regenerate `src/api_proto.rs` from the official ESPHome API definitions.
//!
//! ```sh
//! cargo run -p eam-esphome-api --example regen_proto
//! ```
//!
//! Requires `protoc` on PATH (or the `PROTOC` env var). The generated file is
//! committed so that normal builds and CI do not need protoc installed.

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let proto_dir = concat!(env!("CARGO_MANIFEST_DIR"), "/proto");
    let out_dir = concat!(env!("CARGO_MANIFEST_DIR"), "/src/api_proto.rs");

    // protoc's bundled descriptor.proto, when protoc comes from a local unzip.
    let mut include_paths = vec![proto_dir.to_string()];
    for candidate in [
        "/tmp/opencode/protoc/include",
        "/usr/include",
        "/usr/local/include",
    ] {
        if std::path::Path::new(&format!("{candidate}/google/protobuf/descriptor.proto")).exists() {
            include_paths.push(candidate.to_string());
        }
    }

    prost_build::Config::new()
        .out_dir(
            std::path::Path::new(&out_dir)
                .parent()
                .unwrap()
                .to_str()
                .unwrap(),
        )
        .compile_protos(
            &[
                format!("{proto_dir}/api.proto"),
                format!("{proto_dir}/api_options.proto"),
            ],
            &include_paths.iter().map(String::as_str).collect::<Vec<_>>(),
        )?;

    // prost names the output after the proto path; normalise it to a fixed name.
    let generated = std::path::Path::new(&out_dir)
        .parent()
        .unwrap()
        .join("_.rs");
    let mut text = std::fs::read_to_string(&generated)?;
    let pound = "#";
    let header = [
        "// This file is @generated by prost-build.",
        "//! Protocol message types generated from `proto/api.proto`.",
    ]
    .join("\n")
        + "\n"
        + pound
        + "![allow(missing_docs)]\n"
        + pound
        + "![allow(clippy::all)]\n";
    text.replace_range(..text.find('\n').unwrap_or(0), &header);
    std::fs::write(out_dir, text)?;
    std::fs::remove_file(generated).ok();

    println!("wrote {out_dir}");
    Ok(())
}
